<template>
<section class="calibration"><h4>Calibrate walking distance</h4><p>Measure a straight path (for example 10 m). Start at one end, keep the phone in the same position you use for recording, then walk to the other end.</p><label>Measured path length (m)<input v-model.number="distance" type="number" min="1" max="1000" step="0.1" :disabled="running || disabled" /></label><p><strong>Sensor: {{ stepMethodLabel(method) }}</strong></p><p v-if="method === 'motion-estimate'">Estimated from motion. Confirm the count against your actual steps; rhythmic shaking can resemble walking. Use measured manual distances if this phone cannot track your normal walk.</p><strong v-if="running || count">{{ count }} detected steps</strong><p role="status">{{ message }}</p><p v-if="!running && count" role="status">{{ validation }}</p><p v-if="method === 'hardware-counter'">Counter updates can be delayed. After reaching the marker, stand still and wait for the count to settle before finishing.</p><label v-if="!running && count" class="check"><input v-model="confirmed" type="checkbox" /> The detected step count matches my walk.</label><label v-if="!running"><input v-model="capture" type="checkbox" /> Capture a local sensor trace for troubleshooting (no upload).</label><label v-if="capture && !running">Activity label<select v-model="activity"><option>normal-walking</option><option>slow-walking</option><option>standing</option><option>turning</option><option>shaking</option></select></label><div><button v-if="!running" type="button" :disabled="disabled" @click="start">Start calibration walk</button><button v-else type="button" :disabled="method === null" @click="finish">Finish calibration</button><button v-if="!running && count" type="button" :disabled="!confirmed || disabled || !valid" @click="save">Use calibration</button><button v-if="running" type="button" @click="cancel">Cancel</button><button v-if="!running && samples.length" type="button" @click="exportSamples">Export sensor trace</button></div><p>Sensor unavailable? Use measured manual distances in the route editor.</p><p v-if="profile">Saved: {{ profile.stride.toFixed(2) }} m per step · {{ profile.method }}</p></section>
</template>
<script setup lang="ts">
import { computed,onBeforeUnmount,ref,watch } from 'vue';
import { IndoorStepSource,saveCalibration } from '../services/indoor-steps';
import { calibrateStride,stepMethodLabel,type StrideProfile,type IndoorMeasurement } from '../../../shared/indoor-tracking';
const props=defineProps<{user:string;disabled?:boolean}>();const emit=defineEmits<{calibrated:[StrideProfile];activity:[boolean]}>();
const source=new IndoorStepSource(),distance=ref(10),count=ref(0),running=ref(false),message=ref(''),confirmed=ref(false),profile=ref<StrideProfile|null>(null);const method=ref<IndoorMeasurement|null>(null),capture=ref(false),activity=ref('normal-walking'),samples=ref<unknown[]>([]);let alive=true,request=0,startedAt=0;const elapsed=ref(0);
const validation=computed(()=>{try{if(!method.value)return 'Sensor Unavailable';calibrateStride(distance.value,count.value,method.value);if(elapsed.value>0&&(count.value/(elapsed.value/1000)>3.5))return 'Implausibly fast step count. Repeat the measured walk.';return 'Plausible stride. Check the detected count against your actual steps before saving.';}catch{return 'Count does not produce a plausible stride. Repeat the measured walk; do not shake the phone.';}});
const valid=computed(()=>validation.value.startsWith('Plausible'));
function exportSamples(){const blob=new Blob([JSON.stringify({version:1,activity:activity.value,method:method.value,distance:distance.value,steps:count.value,elapsedMs:elapsed.value,samples:samples.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='1locate-sensor-trace.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
watch(running,value=>emit('activity',value));
async function start(){
 if(running.value||props.disabled)return;
 if(!Number.isFinite(distance.value)||distance.value<1||distance.value>1000){message.value='Enter a measured path length between 1 and 1000 meters.';return;}
 const run=++request;count.value=0;confirmed.value=false;method.value=null;samples.value=[];elapsed.value=0;running.value=true;startedAt=Date.now();message.value='Checking step sensor and permission…';
 try{
  const selected=await source.start((steps,activeMethod)=>{if(run===request&&running.value){method.value=activeMethod;count.value+=steps;}},status=>{if(run!==request)return;if(status==='paused'){cancel();message.value='Calibration interrupted. Repeat the measured walk.';}else message.value=status;},sample=>{if(capture.value&&run===request&&samples.value.length<30000)samples.value.push({...sample});});
  if(!alive||run!==request)return;method.value=selected;
 }catch(error){if(run!==request)return;running.value=false;method.value=null;await source.stop();message.value=(error as Error).message;}
}
function finish(){elapsed.value=Date.now()-startedAt;running.value=false;request++;void source.stop();message.value=count.value?'Review the count and stride before saving.':'No walking steps detected. Retry a normal measured walk or use measured manual distances.';}
function cancel(){request++;running.value=false;void source.stop();count.value=0;}
function save(){try{if(!confirmed.value||props.disabled||!valid.value||!method.value)return;const value=calibrateStride(distance.value,count.value,method.value);profile.value=value;try{saveCalibration(props.user,value);message.value='Calibration saved on this device.';}catch{message.value='Calibration is available this session only; browser storage could not save it.';}emit('calibrated',value);}catch(error){message.value=(error as Error).message;}}
function hidden(){if(document.hidden&&running.value){cancel();message.value='Calibration interrupted. Repeat the measured walk.';}}
document.addEventListener('visibilitychange',hidden);onBeforeUnmount(()=>{alive=false;request++;running.value=false;void source.stop();document.removeEventListener('visibilitychange',hidden);});
</script>
<style scoped>
.calibration{background:#f3f7fc;border:1px solid #dce5ef;border-radius:10px;padding:14px;margin:14px 0;}h4{margin:0 0 8px;}p,label{font-size:12px;line-height:1.6;}button{min-height:44px;padding:10px;border:1px solid #cadaee;border-radius:8px;background:white;color:#174d91;margin:5px 5px 0 0;cursor:pointer;}input[type=number]{display:block;min-height:44px;padding:8px;border:1px solid #cadaee;border-radius:8px;width:100%;box-sizing:border-box;}.check{display:flex;gap:8px;align-items:flex-start;}input[type=checkbox]{width:20px;height:20px;}
</style>
